def read_mesh_state():
    try:
        resp = requests.get(PILOT_REPORT_URL, timeout=5)
        resp.raise_for_status()
        data = resp.json()

        fragility = data.get('aggregate_fragility', 0)
        concordance = data.get('aggregate_concordance', 0)
        elasticity = "UNKNOWN"

        if fragility == 0 and concordance == 0:
            elasticity = "IDLE"
        elif fragility > concordance:
            elasticity = "CONTRACT"
        elif concordance > fragility * 2:
            elasticity = "EXPAND"
        else:
            elasticity = "STABLE"

        print(f"📊 Mesh State Retrieved at: {data.get('last_updated')}")
        print(f"   Fragility: {fragility}")
        print(f"   Concordance: {concordance}")
        print(f"   Elasticity: {elasticity}")

        return {'status': 'OK', 'data': data, 'elasticity': elasticity}

    except Exception as e:
        print(f"❌ Error reading mesh state: {e}")
        return {'status': 'ERROR', 'message': str(e)}

state_result = read_mesh_state()

next_action_params = {}
reasoning = ""

if state_result['status'] == 'OK':
    elasticity = state_result['elasticity']

    if elasticity == "EXPAND":
        # Strategy: Leverage stability to ingest high-value satellite data
        reasoning = "Mesh is expanding. Initiating RADARSAT observation for Goldstream Watershed."
        next_action_params = {
            "template_name": "satellite_observer",
            "agent_name": "wendy_goldstream_sar_v1",
            "config": {
                "target_region": "Goldstream_Watershed",
                "modality": "RADARSAT_SAR",
                "priority": "HIGH"
            }
        }
        command = "spawn_agent"

    elif elasticity == "CONTRACT":
        # Strategy: Halt expansion, resolve epistemic fragility via literature
        reasoning = "High fragility detected. Pausing expansion to resolve IGFBP7 conflict."
        next_action_params = {
            "template_name": "literature_resolver",
            "agent_name": "wendy_igfbp7_fix_v1",
            "config": {
                "gene": "IGFBP7",
                "organism": "Mus_musculus",
                "context": "Spaceflight_Biology_OSDR"
            }
        }
        command = "spawn_agent"

    else: # STABLE or IDLE
        # Strategy: Establish initial ground truth for Spaceflight Biology
        reasoning = "Mesh is stable/idle. Spawning Literature Resolver to establish OSDR baseline for IGFBP7."
        next_action_params = {
            "template_name": "literature_resolver",
            "agent_name": "wendy_baseline_igfbp7_v1",
            "config": {
                "gene": "IGFBP7",
                "organism": "Mus_musculus",
                "context": "Spaceflight_Biology_OSDR"
            }
        }
        command = "spawn_agent"

else:
    reasoning = "Cannot determine state. Defaulting to safe Literature Probe."
    command = "spawn_agent"
    next_action_params = {
        "template_name": "literature_resolver",
        "agent_name": "wendy_safe_probe_v1",
        "config": {
            "gene": "IGFBP7",
            "organism": "Mus_musculus",
            "context": "General"
        }
    }

print(f"🧠 Wendy's Decision: {reasoning}")
